// ── Basic file upload with FormData ──
async function uploadFile(file) {
    const fd = new FormData();
    fd.append('file', file);           // the file
    fd.append('description', 'My photo');  // extra text fields
    fd.append('tags', JSON.stringify(['profile', 'avatar']));

    // Do NOT set Content-Type — browser sets multipart/form-data; boundary=...
    const res = await fetch('/api/upload', {
        method: 'POST',
        body:   fd,
    });

    if (!res.ok) throw new Error(`Upload failed: HTTP ${res.status}`);
    return res.json();  // { url: 'https://cdn.example.com/photo.jpg', id: '...' }
}

// ── Upload with progress (requires XMLHttpRequest) ──
function uploadWithProgress(file, onProgress) {
    return new Promise((resolve, reject) => {
        const fd  = new FormData();
        fd.append('file', file);

        const xhr = new XMLHttpRequest();

        // Track upload progress
        xhr.upload.onprogress = (e) => {
            if (e.lengthComputable) {
                const pct = (e.loaded / e.total * 100).toFixed(1);
                onProgress(Number(pct), e.loaded, e.total);
            }
        };

        xhr.onload  = () => {
            if (xhr.status >= 200 && xhr.status < 300) resolve(JSON.parse(xhr.responseText));
            else reject(new Error(`HTTP ${xhr.status}: ${xhr.statusText}`));
        };
        xhr.onerror = () => reject(new Error('Network error'));

        xhr.open('POST', '/api/upload');
        xhr.send(fd);
    });
}

// ── Drag-and-drop with validation ──
const ALLOWED_TYPES = ['image/jpeg', 'image/png', 'image/webp'];
const MAX_SIZE_MB   = 10;

dropZone.addEventListener('drop', async (e) => {
    e.preventDefault();
    const files = Array.from(e.dataTransfer.files);

    for (const file of files) {
        // Validate before upload
        if (!ALLOWED_TYPES.includes(file.type)) {
            showError(`${file.name}: not a supported image type`);
            continue;
        }
        if (file.size > MAX_SIZE_MB * 1024 * 1024) {
            showError(`${file.name}: exceeds ${MAX_SIZE_MB}MB limit`);
            continue;
        }

        // Show preview
        const previewUrl = URL.createObjectURL(file);
        showPreview(previewUrl, file.name);

        // Upload with progress
        try {
            await uploadWithProgress(file, (pct, loaded, total) => {
                updateProgressBar(pct);  // Update UI
            });
            URL.revokeObjectURL(previewUrl);  // Clean up
        } catch (err) {
            showError(`Upload failed: ${err.message}`);
        }
    }
});
